function maxWindowSum(nums, k) {
  let window = 0
  for (let i = 0; i < k; i++) window += nums[i]
  let best = window
  for (let right = k; right < nums.length; right++) {
    window += nums[right] - nums[right - k]
    best = Math.max(best, window)
  }
  return best
}

